// ── Recipient allowlist gate ───────────────────────────────────────────────
// The MODEL supplies `to`. An attacker who gets a prompt injection into an
// inbound email can therefore choose it. This node is the control that stops
// that turning Hermes into an open relay: a recipient that is not on this list
// aborts the workflow before the SMTP node ever runs.
//
// Keep this list in sync with EMAIL_ALLOWED_USERS in the Hermes .env.
const ALLOWED = [
  // Not committed (public repo): linux/sync_allowlist.py fills this from
  // EMAIL_ALLOWED_USERS + EMAIL_CC_RECIPIENTS in the team .env.
];

const MAX_SUBJECT = 200;
const MAX_BODY = 20000;

// ── Attachment gate ──────────────────────────────────────────────────────────
// The model also supplies `attachments`, so the same injection could ask for
// ~/.hermes/.env. Only files Hermes itself staged for delivery are allowed:
// sandbox_to_drive and inbound email both write to the team profile's
// cache/documents. n8n enforces the same root again on the read
// (N8N_RESTRICT_FILE_ACCESS_TO, realpath'd, so ../ and symlinks can't escape).
const ATTACH_ROOT = '/home/hemang/.hermes/profiles/team/cache/documents/';
const MAX_ATTACHMENTS = 10;
// Gmail refuses these outright (552 5.7.0); fail here with a readable error instead.
const GMAIL_BLOCKED = /\.(ade|adp|apk|appx|appxbundle|bat|cab|chm|cmd|com|cpl|dll|dmg|ex|ex_|exe|hta|ins|isp|iso|jar|js|jse|lib|lnk|mde|msc|msi|msix|msixbundle|msp|mst|nsh|pif|ps1|scr|sct|shb|sys|vb|vbe|vbs|vxd|wsc|wsf|wsh)$/i;

function parseAttachments(raw) {
  if (Array.isArray(raw)) return raw.map(String);
  const s = String(raw ?? '').trim();
  if (!s) return [];
  if (s.startsWith('[')) {
    try { return JSON.parse(s).map(String); } catch (e) { /* fall through */ }
  }
  // One path per line; a comma only separates when the next path starts right after it.
  return s.split(/\n|,\s*(?=MEDIA:|\/)/);
}

function checkAttachment(p) {
  const path = p.trim().replace(/^MEDIA:\s*/i, '');
  if (!path.startsWith(ATTACH_ROOT) || path.includes('/../') || path.includes('/./') || /[*?{}!\0]/.test(path)) {
    throw new Error(`send_email: attachment not permitted: ${path} (only files under ${ATTACH_ROOT}, i.e. the MEDIA: path sandbox_to_drive returns)`);
  }
  if (GMAIL_BLOCKED.test(path)) {
    throw new Error(`send_email: Gmail rejects this file type: ${path} (zip it or rename it, e.g. .txt)`);
  }
  return path;
}

const out = [];
for (const item of $input.all()) {
  const to = String(item.json.to ?? '').trim().toLowerCase();

  if (!to) {
    throw new Error('send_email: "to" is required');
  }
  if (!ALLOWED.includes(to)) {
    // Deliberately explicit: this shows up in the n8n execution log AND comes
    // back to Hermes as a tool error, so a blocked attempt is visible.
    throw new Error(`send_email: recipient not permitted: ${to}`);
  }

  const subject = String(item.json.subject ?? '(no subject)').slice(0, MAX_SUBJECT);
  const body = String(item.json.body ?? '').slice(0, MAX_BODY);
  const attachments = [...new Set(parseAttachments(item.json.attachments).filter(p => p.trim()).map(checkAttachment))];
  if (attachments.length > MAX_ATTACHMENTS) {
    throw new Error(`send_email: at most ${MAX_ATTACHMENTS} attachments`);
  }

  out.push({ json: { to, subject, body, attachments } });
}
return out;

// Read Attachments yields one item per file; the SMTP node wants one item
// carrying every file. Gather them and drop the out_<hash>_ prefix Hermes
// adds when it stages a file, so Uma sees "report.xlsx", not "out_5f7a1dca_report.xlsx".
const mail = $('Guard: recipient allowlist').first().json;
const binary = {};
const props = [];
$input.all().forEach((item, i) => {
  const b = item.binary.data;
  b.fileName = String(b.fileName || `attachment_${i}`).replace(/^out_[0-9a-f]{8}_/, '');
  binary[`file_${i}`] = b;
  props.push(`file_${i}`);
});
return [{ json: { ...mail, fileAttachments: props.join(',') }, binary }];
